<?php require_once __DIR__.'/../app/App.php'; if(Auth::platformCheck())redirect('platform.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{Auth::platformLogin(App::api(),trim($_POST['email']??''),$_POST['password']??'');redirect('platform.php');}catch(Throwable $e){$error=$e->getMessage();}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PassNow Platform</title><link rel="stylesheet" href="../Assets/css/app.css"><link rel="stylesheet" href="../Assets/css/admin.css"></head><body class="platform-login-page"><form class="platform-card" method="post"><h2>PassNow Platform</h2><p>Platform administrator login</p><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif?><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button>Sign in</button></form><script src="../Assets/js/admin.js"></script></body></html>